import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, catchError, map, of, switchMap } from 'rxjs';
import { User, UserRole } from '../models/user.model';
import { NivelGobiernoValue } from '../shared/models/tramite.model';
import { AuthService } from './auth.service';
import { environment } from '../../environments/environment';

export interface UserQueryParams {
  page?: number;
  perPage?: number;
  search?: string;
  role?: string;
}

export interface UserPayload {
  name: string;
  email: string;
  role: UserRole;
  nivel_gobierno?: NivelGobiernoValue | null;
  municipio?: string | null;
}

export interface ProfilePayload {
  name: string;
  email: string;
}

export interface PaginatedUsers {
  users: User[];
  total: number;
  currentPage: number;
  lastPage: number;
  perPage: number;
}

export interface ProfileUpdateResult {
  user: User;
  requiresVerification: boolean;
}

interface RawUser {
  id: number;
  name: string;
  email: string;
  email_verified_at: string | null;
  role: UserRole;
  nivel_gobierno: NivelGobiernoValue | null;
  municipio: string | null;
  created_at: string;
  updated_at: string;
}

interface UserApiResponse {
  data: RawUser[];
  meta: {
    current_page: number;
    last_page: number;
    per_page: number;
    total: number;
  };
}

interface SingleUserResponse {
  data: RawUser;
}

@Injectable({
  providedIn: 'root',
})
export class UserService {
  private readonly http = inject(HttpClient);
  private readonly authService = inject(AuthService);
  private readonly apiUrl = environment.apiUrl;

  getUsers(params: UserQueryParams = {}): Observable<PaginatedUsers> {
    let httpParams = new HttpParams();

    if (params.page) {
      httpParams = httpParams.set('page', params.page.toString());
    }
    if (params.perPage) {
      httpParams = httpParams.set('perPage', params.perPage.toString());
    }
    if (params.search) {
      httpParams = httpParams.set('search', params.search);
    }
    if (params.role) {
      httpParams = httpParams.set('role', params.role);
    }

    return this.http.get<UserApiResponse>(`${this.apiUrl}/users`, { params: httpParams }).pipe(
      map((res) => ({
        users: res.data.map(this.mapRawUser),
        total: res.meta.total,
        currentPage: res.meta.current_page,
        lastPage: res.meta.last_page,
        perPage: res.meta.per_page,
      }))
    );
  }

  getUser(id: number): Observable<User> {
    return this.http.get<SingleUserResponse>(`${this.apiUrl}/users/${id}`).pipe(
      map((res) => this.mapRawUser(res.data))
    );
  }

  createUser(payload: UserPayload): Observable<User> {
    return this.http.post<SingleUserResponse>(`${this.apiUrl}/users`, payload).pipe(
      map((res) => this.mapRawUser(res.data))
    );
  }

  updateUser(id: number, payload: UserPayload): Observable<User> {
    return this.http.put<SingleUserResponse>(`${this.apiUrl}/users/${id}`, payload).pipe(
      map((res) => this.mapRawUser(res.data))
    );
  }

  deleteUser(id: number): Observable<void> {
    return this.http.delete<{ message: string }>(`${this.apiUrl}/users/${id}`).pipe(
      map(() => undefined)
    );
  }

  updateProfile(payload: ProfilePayload): Observable<ProfileUpdateResult> {
    return this.http.patch<SingleUserResponse>(`${this.apiUrl}/user/profile`, payload).pipe(
      switchMap((res) => {
        const user = this.mapRawUser(res.data);

        // Si el correo cambió y quedó sin verificar, forzar el flujo de re-verificación
        if (!user.email_verified_at) {
          this.authService.pendingVerificationEmail.set(user.email);
          return this.authService.logout().pipe(
            map(() => ({
              user,
              requiresVerification: true,
            })),
            catchError(() =>
              of({
                user,
                requiresVerification: true,
              })
            )
          );
        }

        // Sincronizar el estado del usuario autenticado en la sesión
        return this.authService.checkSession().pipe(
          map(() => ({
            user,
            requiresVerification: false,
          }))
        );
      })
    );
  }

  private mapRawUser(raw: RawUser): User {
    return {
      id: raw.id,
      name: raw.name,
      email: raw.email,
      email_verified_at: raw.email_verified_at,
      role: raw.role,
      nivelGobierno: raw.nivel_gobierno,
      nivel_gobierno: raw.nivel_gobierno,
      municipio: raw.municipio,
      created_at: raw.created_at,
    };
  }
}
